{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.grn_issues_joined AS WITH voucher_base AS ( SELECT UPPER(CONCAT(TRIM(COALESCE(GRN_PREFIX, \'\')),\'-\',TRIM(TO_VARCHAR(TRUNC(COALESCE(GRN_NUMBER, 0)))))) AS DOC_KEY, CASE WHEN COALESCE(QUANTITY, 0) = 0 THEN \'GRN Pending\' ELSE \'GRN Done\' END AS GRN_STATUS, CASE WHEN UPPER(TRIM(TO_PARTY)) IN (\'SNITCH - WH - YELHANKA 2\', \'WH - YELHANKA 2\') THEN \'SAPL-WH2\' WHEN UPPER(TRIM(TO_PARTY)) = \'SNITCH - WH - NORTH\' THEN \'SAPL-NORTH-TAURU\' ELSE TRIM(TO_PARTY) END AS WAREHOUSE_NAME, * FROM snitch_db.maplemonk.logic_purchase_voucher WHERE TO_PARTY IN (\'SNITCH - WH - YELHANKA 2\', \'WH - YELHANKA 2\', \'SNITCH - WH - NORTH\') ), po_base1 AS ( SELECT TRIM(CAST(LOT_NUMBER AS VARCHAR)) AS PO_JOIN_KEY, TO_PARTY, PENDING_QTY, TOTAL_QTY, ORDER_DATE FROM snitch_db.maplemonk.logic_purchase_order ), po_base AS ( SELECT PO_JOIN_KEY, TO_PARTY, PENDING_QTY, TOTAL_QTY FROM ( SELECT p.*, ROW_NUMBER() OVER ( PARTITION BY PO_JOIN_KEY, TO_PARTY ORDER BY ORDER_DATE DESC ) AS rw FROM po_base1 p ) WHERE rw = 1 ), rfid_base AS ( SELECT UPPER(TRIM(CAST(\"Doc No\" AS VARCHAR))) AS DOC_NO, \"Site Name\" AS SCANNED_WH, \"Info 1\" AS INFO_1_VENDOR, \"Doc Date\" AS RFID_DOC_DATE, \"Created Time\" AS RFID_CREATED_TIME, \"Matching Status\" AS MATCHING_STATUS, \"Scanning Status\" AS SCANNING_STATUS FROM snitch_db.maplemonk.s3_rfid_inward WHERE \"Doc No\" IS NOT NULL AND TRIM(CAST(\"Doc No\" AS VARCHAR)) <> \'\' ), voucher_with_rfid AS ( SELECT v.*, r.DOC_NO, r.SCANNED_WH, r.INFO_1_VENDOR, r.RFID_DOC_DATE, r.RFID_CREATED_TIME, r.MATCHING_STATUS, r.SCANNING_STATUS, p.PENDING_QTY, p.TOTAL_QTY, CASE WHEN p.PENDING_QTY IS NULL OR p.TOTAL_QTY IS NULL THEN NULL WHEN COALESCE(p.PENDING_QTY,0) <> COALESCE(p.TOTAL_QTY,0) THEN \'GRN Done\' ELSE \'GRN Pending\' END AS GRN_STATUS, CASE WHEN r.MATCHING_STATUS IS NULL THEN NULL WHEN LOWER(r.MATCHING_STATUS) = \'pending\' THEN \'NON RFID\' ELSE \'RFID\' END AS RFID_STATUS, CASE WHEN r.MATCHING_STATUS IS NULL THEN NULL WHEN LOWER(r.MATCHING_STATUS) = \'matching\' THEN \'Ideal\' WHEN LOWER(r.MATCHING_STATUS) = \'mismatch\' THEN \'Imperfect\' WHEN LOWER(r.MATCHING_STATUS) = \'pending\' THEN \'Ratio\' ELSE r.MATCHING_STATUS END AS SHIPMENT_STATUS FROM voucher_base v LEFT JOIN rfid_base r ON v.DOC_KEY = r.DOC_NO LEFT JOIN po_base p ON TRIM(CAST(v.LOT_NUMBER AS VARCHAR)) = p.PO_JOIN_KEY AND TRIM(v.TO_PARTY) = TRIM(p.TO_PARTY) ), issue_base1 AS ( SELECT CREATED_AT_DATE, UPDATED_AT_DATE, EVIDENCE_WITH_HTTPS, ID AS ISSUE_ID, QTY AS ISSUE_QTY, SKU AS ISSUE_SKU, \"Issue\" AS ISSUE, VENDOR AS VENDOR_ISSUE, COMMENTS, EVIDENCE, PO_NUMBER, SUB_ISSUE, CREATED_BY, INVOICE_NUMBER AS ISSUE_INVOICE_NUMBER, CASE WHEN UPPER(TRIM(FACILITY)) = \'WH2\' THEN \'SNITCH - WH - YELHANKA 2\' WHEN UPPER(TRIM(FACILITY)) = \'NORTH_WH\' THEN \'SNITCH - WH - NORTH\' ELSE TRIM(FACILITY) END AS FACILITY_STD, UPPER( COALESCE( REGEXP_SUBSTR(CAST(PO_NUMBER AS VARCHAR), \'POF[0-9]{2}-[0-9]+\', 1, 1, \'i\'), REGEXP_SUBSTR(CAST(PO_NUMBER AS VARCHAR), \'PO[0-9A-Z]{0,10}-[0-9]+\', 1, 1, \'i\'), TRIM(REGEXP_REPLACE(CAST(PO_NUMBER AS VARCHAR), \'^[\\s\\-]+\', \'\')) ) ) AS PO_JOIN_KEY FROM snitch_db.maplemonk.issues_factory_sorted ), issue_base AS ( SELECT CREATED_AT_DATE, UPDATED_AT_DATE, EVIDENCE_WITH_HTTPS, ISSUE_ID, ISSUE_QTY, ISSUE_SKU, ISSUE, VENDOR_ISSUE, COMMENTS, EVIDENCE, PO_NUMBER, SUB_ISSUE, CREATED_BY, ISSUE_INVOICE_NUMBER, FACILITY_STD, PO_JOIN_KEY FROM ( SELECT b.*, ROW_NUMBER() OVER ( PARTITION BY PO_JOIN_KEY, FACILITY_STD ORDER BY UPDATED_AT_DATE DESC ) AS rw FROM issue_base1 b ) WHERE rw = 1 ), item_master1 AS ( SELECT UPPER(TRIM(CAST(SKU AS VARCHAR))) AS SKU_KEY, CATEGORY, PRODUCT_TYPE FROM snitch_db.maplemonk.logic_final_item_master WHERE SKU IS NOT NULL AND TRIM(CAST(SKU AS VARCHAR)) <> \'\' ), item_master AS ( SELECT SKU_KEY, CATEGORY, PRODUCT_TYPE FROM ( SELECT im.*, ROW_NUMBER() OVER ( PARTITION BY SKU_KEY ORDER BY CATEGORY DESC, PRODUCT_TYPE DESC ) AS rw FROM item_master1 im ) WHERE rw = 1 ) SELECT vr.*, im.CATEGORY, im.PRODUCT_TYPE, i.ISSUE_ID, i.CREATED_AT_DATE AS ISSUE_CREATED_AT_DATE, i.UPDATED_AT_DATE AS ISSUE_UPDATED_AT_DATE, i.EVIDENCE_WITH_HTTPS, i.ISSUE_QTY, i.ISSUE_SKU, i.ISSUE, i.SUB_ISSUE, i.VENDOR_ISSUE, i.COMMENTS, i.EVIDENCE, i.PO_NUMBER AS PO_NUMBER_ISSUE, i.PO_JOIN_KEY AS PO_JOIN_KEY_EXTRACTED, i.FACILITY_STD AS ISSUE_FACILITY, i.ISSUE_INVOICE_NUMBER, i.CREATED_BY AS ISSUE_CREATED_BY, CASE WHEN i.ISSUE_ID IS NULL THEN 0 ELSE 1 END AS HAS_DISCREPANCY FROM voucher_with_rfid vr LEFT JOIN issue_base i ON UPPER(TRIM(CAST(vr.LOT_NUMBER AS VARCHAR))) = i.PO_JOIN_KEY AND UPPER(TRIM(vr.TO_PARTY)) = UPPER(TRIM(i.FACILITY_STD)) LEFT JOIN item_master im ON UPPER(TRIM(CAST(vr.SKU AS VARCHAR))) = im.SKU_KEY;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            